LAPLACE TRANSFORMS (p.1022)
f(s)  F(t)
29.3.3  \frac{1}{s^n} \quad (n=1,2,3,\dots)  \frac{t^{n-1}}{(n-1)!}
29.3.4  \frac{1}{\sqrt s}  \frac{1}{\sqrt{\pi t}}
29.3.5  s^{-3/2}  2\sqrt{t/\pi}
29.3.6  s^{-(n+\tfrac12)} \quad (n=1,2,3,\dots)  \frac{2^nt^{n-\tfrac12}}{1\cdot3\cdot5\dots(2n-1)\sqrt\pi}
29.3.7  \frac{\Gamma(k)}{s^k} \quad (k>0) \ ^6  t^{k-1}
29.3.8  \frac{1}{s+a}  e^{-at}
29.3.9  \frac{1}{(s+a)^2}  te^{-at}
29.3.10  \frac{1}{(s+a)^n} \quad (n=1,2,3,\dots)  \frac{t^{n-1}e^{-at}}{(n-1)!}
29.3.11  \frac{\Gamma(k)}{(s+a)^k} \quad (k>0) \ ^6  t^{k-1}e^{-at}
29.3.12  \frac{1}{(s+a)(s+b)} \quad (a\neq b)  \frac{e^{-at}-e^{-bt}}{b-a}
29.3.13  \frac{s}{(s+a)(s+b)} \quad (a\neq b)  \frac{ae^{-at}-be^{-bt}}{a-b}
29.3.14  \frac{1}{(s+a)(s+b)(s+c)}  -\frac{(b-c)e^{-at}+(c-a)e^{-bt}+(a-b)e^{-ct}}{(a-b)(b-c)(c-a)}
(a, b, c distinct constants)
29.3.15  \frac{1}{s^2+a^2}  \frac1a\sin at
29.3.16  \frac{s}{s^2+a^2}  \cos at
29.3.17  \frac{1}{s^2-a^2}  \frac1a\sinh at
29.3.18  \frac{s}{s^2-a^2}  \cosh at
29.3.19  \frac{1}{s(s^2+a^2)}  \frac{1}{a^2}(1-\cos at)
29.3.20  \frac{1}{s^2(s^2+a^2)}  \frac{1}{a^3}(at-\sin at)
29.3.21  \frac{1}{(s^2+a^2)^2}  \frac{1}{2a^3}(\sin at-at\cos at)
